-- Step 2 of the task-loop deletion: run #529's generic conversion (0026, from "Every database" on) again,
-- for any task-loop run that ended between that deploy and this one. Idempotent.
-- Every database, whatever its runs hold. Task runs are those with no harness or "tasks"; only
-- ended ones are touched, since a live task-loop run still needs its task events, and a listed run
-- whose INSERT did not apply is left alone.
-- A payload holding \u0000 makes the jsonb casts and ->> below fail, which aborts the migration; the
-- staging runs hold it only in tool.result, which no statement here reads.
-- reply -> agent.message
UPDATE "events"
SET "type" = 'agent.message',
    "payload" = jsonb_build_object('from', 'main', 'to', 'researcher', 'text', "payload"->>'text')::json
WHERE "type" = 'reply'
  AND "run_id" IN (SELECT "id" FROM "runs" WHERE ("harness" IS NULL OR "harness" = 'tasks') AND "state" = 'ended'
    AND "id" NOT IN (
      SELECT o."run_id" FROM "events" o
      JOIN (VALUES ('097bb696-ec3e-446f-b6cd-bf8c571486bb.supervisor:revision', 'convert:097bb696-ec3e-446f-b6cd-bf8c571486bb:%'), ('0f9c3bbd-bd3a-4bee-b294-5be3f18902f5.supervisor:revision', 'convert:0f9c3bbd-bd3a-4bee-b294-5be3f18902f5:%'), ('3780cacd-f969-4de8-87e1-88c918154900.supervisor:revision', 'convert:3780cacd-f969-4de8-87e1-88c918154900:%'), ('3c742df1-47ab-447f-bbac-d5e2b18e6d03.supervisor:revision', 'convert:3c742df1-47ab-447f-bbac-d5e2b18e6d03:%'), ('4707c3b4-5bba-43ef-ba62-9a7014d9c7ac.supervisor:revision', 'convert:4707c3b4-5bba-43ef-ba62-9a7014d9c7ac:%'), ('4870652e-4545-49cc-9804-2bc9de6a23a1.supervisor:revision', 'convert:4870652e-4545-49cc-9804-2bc9de6a23a1:%'), ('49257af3-9a47-48a8-8f16-2a691d8fa07e.supervisor:revision', 'convert:49257af3-9a47-48a8-8f16-2a691d8fa07e:%'), ('5b3bcf0f-f104-4a69-9a60-f75b53b785b9.supervisor:revision', 'convert:5b3bcf0f-f104-4a69-9a60-f75b53b785b9:%'), ('68eb632f-44ac-4a80-9fa3-8b16bc4e1f03.supervisor:revision', 'convert:68eb632f-44ac-4a80-9fa3-8b16bc4e1f03:%'), ('778f0937-9395-414c-8e31-03d4266fb153.supervisor:revision', 'convert:778f0937-9395-414c-8e31-03d4266fb153:%'), ('3f2ddc16-0ce9-512d-9c82-d6280a031a28:revision', 'convert:81942c77-3904-461a-9a93-2560ebb1c4e6:%'), ('33cf2758-2f3f-5b01-8bd6-b2cb6ea13d80:revision', 'convert:8b05ef94-439e-4cdb-aed7-2bc936bb1590:%'), ('8b371792-2313-45b0-a294-1ad876aa0b1d.supervisor:revision', 'convert:8b371792-2313-45b0-a294-1ad876aa0b1d:%'), ('8cf62044-32b1-42b8-be78-0e312f0d78f3.supervisor:revision', 'convert:8cf62044-32b1-42b8-be78-0e312f0d78f3:%'), ('a6548e5b-7622-49f3-8817-9024eae0801f.supervisor:revision', 'convert:a6548e5b-7622-49f3-8817-9024eae0801f:%'), ('ce5a0f21-c948-4e20-a03f-04ff7f0e707b.supervisor:revision', 'convert:ce5a0f21-c948-4e20-a03f-04ff7f0e707b:%'), ('d19d4dd0-10c5-45bf-a717-3d691357999e.supervisor:revision', 'convert:d19d4dd0-10c5-45bf-a717-3d691357999e:%'), ('d1b9cb89-fd2d-4112-b363-0b5ad151a886.supervisor:revision', 'convert:d1b9cb89-fd2d-4112-b363-0b5ad