      WHERE NOT EXISTS (SELECT 1 FROM "events" c WHERE c."run_id" = o."run_id" AND c."id" LIKE p."marker")
    ))
  AND CASE WHEN "type" = 'thread.started' THEN "payload"->>'parentThreadId' END IS NULL;
